1	using TutorFlow.Core.Autorizacion;
2	using TutorFlow.Core.Conocimiento;
3	
4	namespace TutorFlow.Core.Asistente;
5	
6	public enum EstadoConversacion
7	{
8	    Completada,
9	    Rechazada,
10	    LimiteHerramientas,
11	    IdAjeno,
12	    ContextoTruncado
13	}
14	
15	public sealed record ResultadoConversacion(
16	    EstadoConversacion Estado,
17	    string? Texto,
18	    string? IdSolicitado = null,
19	    IReadOnlyList<MensajeLlm>? Mensajes = null,
20	    int Invocaciones = 0);
21	
22	internal sealed record EntradaConversacion(
23	    string Pregunta,
24	    IReadOnlyList<SeccionDocumento> Secciones,
25	    ResumenEntregado? Resumen,
26	    string? Prelectura,
27	    string PromptSistema);
28	
29	internal sealed class ConversacionLlm
30	{
31	    private readonly IClienteLlm _clienteLlm;
32	    private readonly HerramientasAsistente _herramientas;
33	    private readonly LimitesAsistente _limites;
34	    private readonly UsoAcumulado _uso;
35	    private readonly ConfiguracionAsistente _configuracion;
36	
37	    public ConversacionLlm(
38	        IClienteLlm clienteLlm,
39	        HerramientasAsistente herramientas,
40	        LimitesAsistente limites,
41	        UsoAcumulado uso,
42	        ConfiguracionAsistente configuracion)
43	    {
44	        _clienteLlm = clienteLlm;
45	        _herramientas = herramientas;
46	        _limites = limites;
47	        _uso = uso;
48	        _configuracion = configuracion;
49	    }
50	
51	    public async Task<ResultadoConversacion> EjecutarAsync(
52	        ContextoUsuario contexto,
53	        EntradaConversacion entrada,
54	        RegistroConsultas registro,
55	        CancellationToken cancellationToken)
56	    {
57	        var estado = new Turnos(
58	            contexto,
59	            registro,
60	            [ConstructorPrompts.MensajeInicial(entrada.Pregunta, entrada.Secciones, entrada.Resumen, entrada.Prelectura)],
61	            entrada.PromptSistema);
62	        return await CorrerAsync(estado, cancellationToken);
63	    }
64	
65	    public async Task<ResultadoConversacion> ReintentarAsync(
66	        ContextoUsuario contexto,
67	        string promptSistema,
68	        ResultadoConversacion anterior,
69	        string instruccion,
70	        RegistroConsultas registro,
71	        CancellationToken cancellationToken)
72	    {
73	        List<MensajeLlm> mensajes =
74	        [
75	            .. anterior.Mensajes ?? [],
76	            new MensajeLlm(RolMensaje.Asistente, anterior.Texto ?? string.Empty, null, []),
77	            new MensajeLlm(RolMensaje.Usuario, instruccion, null, [])
78	        ];
79	        return await CorrerAsync(new Turnos(contexto, registro, mensajes, promptSistema) { Invocaciones = anterior.Invocaciones }, cancellationToken);
80	    }
81	
82	    private async Task<ResultadoConversacion> CorrerAsync(Turnos estado, CancellationToken cancellationToken)
83	    {
84	        ResultadoConversacion? final = null;
85	        while (final is null)
86	        {
87	            final = await AvanzarAsync(estado, cancellationToken);
88	        }
89	
90	        return final;
91	    }
92	
93	    private async Task<ResultadoConversacion?> AvanzarAsync(Turnos estado, CancellationToken cancellationToken)
94	    {
95	        var respuesta = await _clienteLlm.CompletarAsync(Solicitar(estado), cancellationToken);
96	        _uso.Sumar(respuesta.Uso);
97	        estado.Invocaciones += respuesta.Llamadas.Count;
98	        var terminal = Terminal(estado, respuesta);
99	        return terminal ?? await EjecutarHerramientasAsync(estado, respuesta, cancellationToken);
100	    }
101	
102	    private ResultadoConversacion? Terminal(Turnos estado, RespuestaLlm respuesta)
103	    {
104	        if (respuesta.ContextoTruncado is { } truncado)
105	        {
106	            return ContextoTruncado(truncado);
107	        }
108	
109	        if (respuesta.Rechazada)
110	        {
111	            return new ResultadoConversacion(EstadoConversacion.Rechazada, null);
112	        }
113	
114	        return respuesta.Llamadas.Count == 0 ? Completada(estado, respuesta) : LimiteSuperado(estado);
115	    }
116	
117	    private static ResultadoConversacion Completada(Turnos estado, RespuestaLlm respuesta) =>
118	        new(EstadoConversacion.Completada, respuesta.Texto, null, [.. estado.Mensajes], estado.Invocaciones);
119	
120	    private ResultadoConversacion? LimiteSuperado(Turnos estado) =>
121	        estado.Invocaciones > _limites.MaximoInvocacionesHerramientas
122	            ? new ResultadoConversacion(EstadoConversacion.LimiteHerramientas, null)
123	            : null;
