108	    {
109	        var id = solicitud.Contexto.Usuario.Id;
110	        var resumen = await ResumirAsync(id, solicitud.CancellationToken);
111	        solicitud.Registro.RegistrarDatos(DatosLeidos.PorAsignatura(resumen, ProgramaDe(solicitud, id), RecursoConsultado.Notas, RecursoConsultado.Asistencia));
112	        solicitud.Registro.RegistrarResumen(resumen);
