132	    private async Task<ResultadoHerramienta> ConsultarAsistencia(SolicitudHerramienta solicitud)
133	    {
134	        var id = solicitud.Contexto.Usuario.Id;
135	        var resumen = await ResumirAsync(id, solicitud.CancellationToken);
136	        solicitud.Registro.RegistrarDatos(DatosLeidos.PorAsignatura(resumen, ProgramaDe(solicitud, id), RecursoConsultado.Notas, RecursoConsultado.Asistencia));
