207	    private static IEnumerable<DatoConsultado> DatosDeEstudiante(Estudiante estudiante, ResumenEstudiante resumen, RecursoConsultado recursoSinAsignatura) =>
208	        DatosLeidos.PorAsignatura(resumen, estudiante.ProgramaId, RecursoConsultado.Notas, RecursoConsultado.Asistencia)
209	            .Prepend(DatosLeidos.SinAsignatura(estudiante.Id, estudiante.ProgramaId, recursoSinAsignatura));
210	
211	    private static string ConReglas(SolicitudHerramienta solicitud, string contenido, IReadOnlyList<int> entradas)
212	    {
213	        solicitud.Registro.RegistrarReglas(entradas);
214	        var reglas = ReglasAplicadas.Citas(entradas);
215	        return reglas.Count == 0 ? contenido : $"{contenido}\n{FormateadorResumen.LineaDeReglas(reglas)}";
216	    }
217	
218	    private static ResultadoHerramienta Responder(
219	        SolicitudHerramienta solicitud,
220	        string contenido,
221	        string estudianteId,
222	        IEnumerable<RecursoConsultado> recursos,
223	        string seccion)
224	    {
225	        var cita = new Cita(Textos.DocumentoDatosEstudiante, seccion);
226	        solicitud.Registro.Registrar(estudianteId, recursos, cita);
227	        return ResultadoHerramienta.Texto(FormateadorDatos.Delimitar($"{cita.Documento} · {cita.Seccion}", contenido));
228	    }
