167	    private async Task<ResultadoHerramienta> ConsultarPrograma(SolicitudHerramienta solicitud)
168	    {
169	        var programas = _politicaAcceso.ProgramasAutorizados(solicitud.Contexto.Usuario, solicitud.Contexto.Directorio);
170	        if (programas.Count == 0)
171	        {
172	            return ResultadoHerramienta.Texto(Textos.SinProgramasAsignados);
173	        }
174	
175	        var bloques = new List<string>();
176	        foreach (var programa in solicitud.Contexto.Directorio.Programas.Where(p => programas.Contains(p.Id)))
177	        {
178	            bloques.Add(await DescribirProgramaAsync(solicitud, programa));
179	        }
180	
181	        return ResultadoHerramienta.Texto(string.Join("\n\n", bloques));
182	    }
