184	    private async Task<string> DescribirProgramaAsync(SolicitudHerramienta solicitud, Programa programa)
185	    {
186	        var estudiantes = solicitud.Contexto.Directorio.Estudiantes.Where(e => e.ProgramaId == programa.Id).ToList();
187	        var datos = new List<EstudianteDePrograma>();
188	        var resumenes = new List<ResumenEstudiante>();
189	        foreach (var estudiante in estudiantes)
190	        {
191	            var resumen = await ResumirAsync(estudiante.Id, solicitud.CancellationToken);
192	            resumenes.Add(resumen);
193	            datos.Add(new EstudianteDePrograma(estudiante, resumen));
194	            solicitud.Registro.Registrar(estudiante.Id, [RecursoConsultado.Programa, RecursoConsultado.Notas, RecursoConsultado.Asistencia], null);
195	            solicitud.Registro.RegistrarDatos(DatosDeEstudiante(estudiante, resumen, RecursoConsultado.Programa));
196	            solicitud.Registro.RegistrarResumen(resumen);
197	        }
198	
199	        solicitud.Registro.RegistrarCita(new Cita(Textos.DocumentoDatosPrograma, programa.Id));
200	        var contenido = ConReglas(solicitud, FormateadorPrograma.Bloque(programa, datos), ReglasAplicadas.DePrograma(resumenes));
201	        return FormateadorDatos.Delimitar($"{Textos.DocumentoDatosPrograma} · {programa.Id}", contenido);
202	    }
