1	using System.ClientModel;
2	using System.ClientModel.Primitives;
3	using System.Net;
4	using System.Text.Json;
5	using Microsoft.Extensions.AI;
6	using OpenAI;
7	using TutorFlow.Core.Asistente;
8	
9	namespace TutorFlow.Infrastructure.Llm;
10	
11	public sealed class ClienteLlmCompatibleOpenAi : IClienteLlm
12	{
13	    private const string LlaveParaServidoresSinAutenticacion = "sin-llave";
14	    private const string SegmentoDeVersion = "v1/";
15	    private const int ReintentosMaximos = 0;
16	    private const string EncabezadoRetryAfter = "Retry-After";
17	    private const string MensajeDelProveedor = "El proveedor del LLM respondió con un error.";
18	
19	    private readonly IChatClient _cliente;
20	    private readonly string _modelo;
21	    private readonly bool _controlaContexto;
22	
23	    public ClienteLlmCompatibleOpenAi(HttpClient httpClient, ProveedorResuelto proveedor, string? llave)
24	    {
25	        _modelo = proveedor.Modelo;
26	        _controlaContexto = proveedor.Proveedor == ProveedorLlm.Ollama;
27	        var opciones = new OpenAIClientOptions
28	        {
29	            Endpoint = ConstruirEndpoint(proveedor.UrlBase),
30	            Transport = new HttpClientPipelineTransport(httpClient),
31	            RetryPolicy = new ClientRetryPolicy(ReintentosMaximos)
32	        };
33	        var credencial = new ApiKeyCredential(string.IsNullOrWhiteSpace(llave) ? LlaveParaServidoresSinAutenticacion : llave);
34	        _cliente = new OpenAIClient(credencial, opciones).GetChatClient(proveedor.Modelo).AsIChatClient();
35	    }
36	
37	    public async Task<RespuestaLlm> CompletarAsync(SolicitudLlm solicitud, CancellationToken cancellationToken)
38	    {
39	        var opciones = new ChatOptions
40	        {
41	            ModelId = _modelo,
42	            MaxOutputTokens = solicitud.MaximoTokensSalida,
43	            Temperature = (float)solicitud.Temperatura,
44	            
45	            Tools = [.. solicitud.Herramientas.Select(Declarar)]
46	        };
47	        try
48	        {
49	            var respuesta = await _cliente.GetResponseAsync(Mensajes(solicitud), opciones, cancellationToken);
50	            return ConControlDeContexto(solicitud, Traducir(respuesta), respuesta.Usage?.InputTokenCount is not null);
51	        }
52	        catch (ClientResultException excepcion)
53	        {
54	            RegistrarDiagnostico(excepcion);
55	            throw new DependenciaNoDisponibleException(MensajeDelProveedor, RetryAfterDe(excepcion));
56	        }
57	    }
58	
59	    private static void RegistrarDiagnostico(ClientResultException excepcion)
60	    {
61	        var cuerpo = excepcion.GetRawResponse()?.Content.ToString() ?? excepcion.Message;
62	        Console.Error.WriteLine($"warn: DIAG llm {excepcion.Status} {(cuerpo.Length > 500 ? cuerpo[..500] : cuerpo)}");
63	    }
64	
65	    private static string? RetryAfterDe(ClientResultException excepcion) =>
66	        excepcion.Status == (int)HttpStatusCode.TooManyRequests && excepcion.GetRawResponse() is { } respuesta && respuesta.Headers.TryGetValue(EncabezadoRetryAfter, out var valor)
67	            ? valor
68	            : null;
69	
70	    private RespuestaLlm ConControlDeContexto(SolicitudLlm solicitud, RespuestaLlm respuesta, bool usoReportado) =>
71	        _controlaContexto && usoReportado ? respuesta with { ContextoTruncado = EstimadorDeContexto.Evaluar(solicitud, respuesta.Uso) } : respuesta;
72	
73	    private static Uri ConstruirEndpoint(string urlBase)
74	    {
75	        var raiz = new Uri(urlBase.TrimEnd('/') + "/");
76	        return raiz.AbsolutePath == "/" ? new Uri(raiz, SegmentoDeVersion) : raiz;
77	    }
78	
79	    private static List<ChatMessage> Mensajes(SolicitudLlm solicitud)
80	    {
81	        var mensajes = new List<ChatMessage> { new(ChatRole.System, solicitud.PromptSistema) };
82	        mensajes.AddRange(solicitud.Mensajes.Select(Mensaje));
83	        return mensajes;
84	    }
85	
86	    private static ChatMessage Mensaje(MensajeLlm mensaje) => mensaje.Rol switch
87	    {
88	        RolMensaje.Herramienta => new ChatMessage(ChatRole.Tool, [new FunctionResultContent(mensaje.IdLlamada ?? string.Empty, mensaje.Contenido)]),
89	        RolMensaje.Asistente => MensajeDeAsistente(mensaje),
90	        _ => new ChatMessage(ChatRole.User, mensaje.Contenido)
91	    };
92	
93	    private static ChatMessage MensajeDeAsistente(MensajeLlm mensaje)
94	    {
95	        var contenidos = new List<AIContent>();
96	        if (!string.IsNullOrEmpty(mensaje.Contenido))
97	        {
98	            contenidos.Add(new TextContent(mensaje.Contenido));
99	        }
100	
101	        contenidos.AddRange(mensaje.Llamadas.Select(llamada =>
102	            llamada.Opaco as AIContent ?? new FunctionCallContent(llamada.Id, llamada.Nombre, ArgumentosDe(llamada.ArgumentosJson))));
103	        return new ChatMessage(ChatRole.Assistant, contenidos) { RawRepresentation = MensajeOriginal(mensaje) };
104	    }
105	
106	    private static OpenAI.Chat.AssistantChatMessage? MensajeOriginal(MensajeLlm mensaje)
107	    {
108	        var original = mensaje.Llamadas.Select(l => (l.Opaco as FunctionCallContent)?.RawRepresentation).OfType<OpenAI.Chat.ChatToolCall>().ToList();
109	        return original.Count > 0 && original.Count == mensaje.Llamadas.Count ? new OpenAI.Chat.AssistantChatMessage(original) : null;
110	    }
111	
112	    private static Dictionary<string, object?> ArgumentosDe(string argumentosJson)
113	    {
114	        using var documento = JsonDocument.Parse(argumentosJson);
115	        return documento.RootElement.ValueKind == JsonValueKind.Object
116	            ? documento.RootElement.EnumerateObject().ToDictionary(p => p.Name, p => (object?)p.Value.Clone())
117	            : [];
118	    }
119	
120	    private static AIFunctionDeclaration Declarar(HerramientaLlm herramienta)
121	    {
122	        var propiedades = herramienta.Parametros.ToDictionary(
123	            parametro => parametro.Nombre,
124	            parametro => new { type = "string", description = parametro.Descripcion });
125	        var esquema = JsonSerializer.SerializeToElement(new
126	        {
127	            type = "object",
128	            properties = propiedades,
129	            required = herramienta.Parametros.Where(p => p.Requerido).Select(p => p.Nombre).ToArray()
130	        });
131	        return AIFunctionFactory.CreateDeclaration(herramienta.Nombre, herramienta.Descripcion, esquema);
132	    }
133	
134	    private static RespuestaLlm Traducir(ChatResponse respuesta)
135	    {
136	        var rechazada = EsRechazo(respuesta);
137	        var texto = rechazada ? null : respuesta.Text;
138	        return new RespuestaLlm(
139	            string.IsNullOrEmpty(texto) ? null : texto,
140	            LlamadasDe(respuesta),
141	            UsoDe(respuesta.Usage),
142	            rechazada);
143	    }
144	
145	    private static bool EsRechazo(ChatResponse respuesta) =>
146	        respuesta.FinishReason == ChatFinishReason.ContentFilter
147	        || (respuesta.RawRepresentation is OpenAI.Chat.ChatCompletion completado && !string.IsNullOrEmpty(completado.Refusal));
148	
149	    private static List<LlamadaHerramienta> LlamadasDe(ChatResponse respuesta) =>
150	        [.. respuesta.Messages
151	            .SelectMany(mensaje => mensaje.Contents)
152	            .OfType<FunctionCallContent>()
153	            .Select(llamada => new LlamadaHerramienta(llamada.CallId, llamada.Name, JsonSerializer.Serialize(llamada.Arguments ?? new Dictionary<string, object?>()), llamada))];
154	
155	    private static UsoTokens UsoDe(UsageDetails? uso) =>
156	        new((int)(uso?.InputTokenCount ?? 0), (int)(uso?.OutputTokenCount ?? 0));
157	}
